INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(20001, 'Ezekiel 26:16', 'Ezekiel', 26, 16, '&nbsp;نو بيا به د ساحل ټول شهزادګان د خپلو تختونو نه راکوز شى او خپله چُوغه به وباسى او خپلې د ګُلکارۍ جامې به يوې خوا ته کېږدى. هغوئ به د غم لباس واچوى په زمکه به کښېنى او د يرې نه به ريږدى، او ستا په تباهۍ به خفه کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20002, 'Ezekiel 26:17', 'Ezekiel', 26, 17, '&nbsp;نو بيا به هغوئ ستا په حقله د غم په مرثيو کښې داسې وائى، تۀ څنګه تباه شوې، د سمندرونو خلق به ستاسو مُلک قبضه کړى، اے مشهورې ښاريې، يو وخت داسې وو چې تا په سمندر بادشاهى کوله او په ټوله دُنيا مو يره خوره کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20003, 'Ezekiel 26:18', 'Ezekiel', 26, 18, '&nbsp;نو اوس ساحلى علاقه ستا د راغورزېدلو په ورځ لړزيږى، په سمندر کښې جزيرې ستا په راغورزېدلو په لړزان شوې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20004, 'Ezekiel 26:19', 'Ezekiel', 26, 19, '&nbsp;مالِک قادر مطلق خُدائ داسې فرمائى چې، کله چې زۀ ستا ښار په کنډرو بدل کړم، لکه د هغه ښار په شان چې په کښې کله څوک نۀ وى آباد شوى، او کله چې زۀ د سمندر د تل نه اوبۀ په تا راوخېژوم او په هغه ډوبو اوبو کښې غرق شې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20005, 'Ezekiel 26:20', 'Ezekiel', 26, 20, '&nbsp;نو بيا به زۀ تا د هغه چا سره لاندې کندې ته بوځم، هغه خلقو له څوک چې ډېر وړاندې تېر شوى دى. او زۀ به تا په لاندې زمکه کښې اوسوم، لکه د پخوانو تباه شوو سره به اوسيږى، د هغوئ سره څوک چې لاندې کندې ته روان وى، نو تۀ به بيا هيڅکله راواپس نۀ شې او نۀ به د ژوندو په دُنيا کښې خپل ځائ ته ورسېږې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20006, 'Ezekiel 26:21', 'Ezekiel', 26, 21, '&nbsp;زۀ به تاسو په دردناک مرګ ووژنم او تۀ به نور په دُنيا کښې نۀ يې. ستا لټون به کولے شى خو تۀ به هيڅکله نۀ پېدا کېږې. مالِک قادر مطلق داسې فرمائى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20007, 'Ezekiel 27:1', 'Ezekiel', 27, 1, '&nbsp;د مالِک خُدائ کلام په ما نازل شو چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20008, 'Ezekiel 27:2', 'Ezekiel', 27, 2, '&nbsp;”اے بنى آدمه، د صور په حقله د غم مرثيه ووايه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20009, 'Ezekiel 27:3', 'Ezekiel', 27, 3, '&nbsp;صور ته ووايه، چې تۀ د سمندر په غاړه پروت يې او د سمندر د غاړې ډېرو خلقو سره تجارت کوې، مالِک قادر مطلق خُدائ فرمائى چې، اے صوره تا د خپل ځان په حقله وئيل چې زما د ښائست جواب نشته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20010, 'Ezekiel 27:4', 'Ezekiel', 27, 4, '&nbsp;ستا حدونه د سمندر مينځ پورې رسېدلى دى. ستا جوړونکو ستا ښائست لاجوابه جوړ کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20011, 'Ezekiel 27:5', 'Ezekiel', 27, 5, '&nbsp;تۀ لکه د سمندر د هغه کشتۍ په شان وې چې د حرمون د غرۀ د نختر لرګى نه جوړه شوې وې او هغوئ د دِيار لرګى د لبنان نه راوړل چې ستا دپاره يوه ستن ترې جوړه کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20012, 'Ezekiel 27:6', 'Ezekiel', 27, 6, '&nbsp;هغوئ د څېړۍ لرګى د بسن نه راوړل او ستا د چلولو چپو يې ترې جوړ کړل، هغوئ ستا فرش د قبرص د نخترو نه جوړ کړو په دې باندې يې د هاتى د غاښونو کار وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20013, 'Ezekiel 27:7', 'Ezekiel', 27, 7, '&nbsp;ستا بادبان د مِصر د ګُلکارۍ د کتان نه جوړ وو، او دا ستا په سر باندې لکه د جنډې په شان رپېدو، ستا شاميانه د کاسنى او آسمانى رنګى کپړې وه چې د اِليسه د ساحلى علاقې نه راوړلے شوې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20014, 'Ezekiel 27:8', 'Ezekiel', 27, 8, '&nbsp;د صيدا او ارود کسان ستا چپو وهونکى وُو. اے صوره، ستا هوښيار کسان ستا ماڼکيان وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20015, 'Ezekiel 27:9', 'Ezekiel', 27, 9, '&nbsp;د جبل د علاقې نه په کار پوهه او هوښيار کسان په کشتۍ کښې وُو چې ستا چاؤدونه بند کړى. د سمندر ټولې کشتۍ او د دې ماڼکيان راغلل چې ستا د مال تجارت وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20016, 'Ezekiel 27:10', 'Ezekiel', 27, 10, '&nbsp;د فارس، لِديه او ليبيا فوجيان ستا په لښکر کښې شامل وُو. هغوئ خپل ډالونه او ټوپۍ ستا په دېوالونو راځوړند کړل چې تا ته شان و شوکت مِلاو شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20017, 'Ezekiel 27:11', 'Ezekiel', 27, 11, '&nbsp;د ارود او د حيلک سړو د هرې خوا نه ستا د دېوالونو حفاظت وکړو، او د جماد خلق ستا په برجونو کښې وُو. هغوئ خپل ډالونه ستا په دېوالونو راځوړند کړل، هغوئ ستا حُسن مکمل کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20018, 'Ezekiel 27:12', 'Ezekiel', 27, 12, '&nbsp;ترسيس تا سره کاروبار وکړلو ځکه چې تا سره هر قسم سامان ډېر زيات مِلاوېدلو، او ستا د څيزونو په بدله کښې هغوئ تا ته سپين زر، اوسپنه، ټيم او سيکه درکوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20019, 'Ezekiel 27:13', 'Ezekiel', 27, 13, '&nbsp;يونان، توبل او مسک تا سره کاروبار وکړو، هغوئ ستاسو د سامان په بدل کښې غلامان او د زېړو څيزونه درکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20020, 'Ezekiel 27:14', 'Ezekiel', 27, 14, '&nbsp;د بيت‌تُجرمه خلقو د څيزونو په بدل کښې تاسو له آسونه، جنګى آسونه او قچرې درکړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20021, 'Ezekiel 27:15', 'Ezekiel', 27, 15, '&nbsp;د ددان خلقو تاسو سره کاروبار وکړو، او د ډېرو ساحلى علاقو خلق ستا ګاهکان وُو، هغوئ تا ته د هاتى غاښونه او د آبنوس لرګى درکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20022, 'Ezekiel 27:16', 'Ezekiel', 27, 16, '&nbsp;د شام خلقو تا سره کاروبار وکړو ځکه چې په تا کښې هر قسم څيز مِلاوېدو، هغوئ ستا د سامان په بدله کښې تا له زمرد کاڼى کاسنى او آسمانى رنګى کپړې، ګُلکارى، نرم کتان، مرجان او ياقوت درکول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20023, 'Ezekiel 27:17', 'Ezekiel', 27, 17, '&nbsp;يهوداه او بنى اِسرائيلو تا سره کاروبار وکړو، او هغوئ ستا د څيزونو په بدله کښې تا ته د مِنيت نه غنم، اينځر، شات، د ‎زيتُونو تېل او مصالحې درکړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20024, 'Ezekiel 27:18', 'Ezekiel', 27, 18, '&nbsp;دمشق تا سره د ډېر پېداوار او د مال د زياتوالى په وجه، کاروبار وکړو او د دې څيزونو په بدله کښې يې د حلبون مے او د صاحر وړۍ درکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20025, 'Ezekiel 27:19', 'Ezekiel', 27, 19, '&nbsp;د ودان او يونان خلقو ستاسو نه څيزونه اخستل او د هغې په بدله کښې يې تاسو ته د کار اوسپنه او خوشبودارې مصالحې درکولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20026, 'Ezekiel 27:20', 'Ezekiel', 27, 20, '&nbsp;د ددان خلقو د آسونو د قيمتى زينونو کاروبار تاسو سره کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20027, 'Ezekiel 27:21', 'Ezekiel', 27, 21, '&nbsp;د عربو او د قيدار ټول شهزادګان ستا خريدار وُو، هغوئ تاسو سره د ګډورو، ګډانو، او چېلو کاروبار وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20028, 'Ezekiel 27:22', 'Ezekiel', 27, 22, '&nbsp;د شيبا او راماه خلقو تا سره کاروبار وکړو، ستاسو د څيزونو په بدله کښې هغوئ تاسو له اعلىٰ مصالحې، قيمتى کاڼى او سرۀ زر درکول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20029, 'Ezekiel 27:23', 'Ezekiel', 27, 23, '&nbsp;د حاران، کنه او عدن، د شيبا سوداګرو او د اسور او کِلمد خلقو هم تا سره تجارت وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20030, 'Ezekiel 27:24', 'Ezekiel', 27, 24, '&nbsp;ستاسو په بازارونو کښې هغوئ تاسو سره د ښکلې کپړې، د آسمانې رنګې کپړې، د ګُلکارۍ او د رنګينه قالينونو چې پړى ترې تاو وُو او چې ګُلکارۍ يې کلکې تړلے شوې وې کاروبار وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20031, 'Ezekiel 27:25', 'Ezekiel', 27, 25, '&nbsp;د ترسيس بيړو ستا د سامان په وړولو کښې مدد کولو، او د سمندر په زړۀ کښې تۀ د دروند مال نه ډکه وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20032, 'Ezekiel 27:26', 'Ezekiel', 27, 26, '&nbsp;ستا چپو وهونکو تۀ لوئ سمندر ته راورسولې، خو د مشرق هواګانې به تا د سمندر په مينځ کښې ماته کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20033, 'Ezekiel 27:27', 'Ezekiel', 27, 27, '&nbsp;ستا مال دولت، د تجارت سامان او مال، ستا د بيړۍ ټول چلوونکى، جوړونکى او پوهان، ستا تاجران، او ستا ټول فوجيان، او نور ټول هغه کسان چې په کشتۍ کښې ناست دى به د سمندر په زړۀ کښې ډوب شى په کومه ورځ چې ستا کشتۍ تباه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20034, 'Ezekiel 27:28', 'Ezekiel', 27, 28, '&nbsp;ستا د ماڼکيانو د چغو په وجه به د سمندر په غاړه خلق د يرې نه ولړزيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20035, 'Ezekiel 27:29', 'Ezekiel', 27, 29, '&nbsp;هغه ټول چپو وهونکى به خپله کشتۍ پرېږدى، ماڼکيان او نور کار کوونکى به د ساحل په غاړه ودريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20036, 'Ezekiel 27:30', 'Ezekiel', 27, 30, '&nbsp;هغوئ به خپل آواز اوچت کړى او په تا به سخته ژړا کوى، هغوئ به په خپلو سرونو خاورې او دوړې وشيندى او په ايرو کښې به ورغړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20037, 'Ezekiel 27:31', 'Ezekiel', 27, 31, '&nbsp;هغوئ به ستا په وجه خپل سرونه ګنجى کړى او د ټاټ جامې به واچوى. هغوئ به په تا په پرېشانه زړۀ سره ژړا وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20038, 'Ezekiel 27:32', 'Ezekiel', 27, 32, '&nbsp;کله چې هغوئ په تا باندې ژړا او وير کوى، هغوئ به ستا په حقله د غم مرثيه وائى، څوک لکه د صور په شان خاموشه وو، چې سمندر يې محاصره کړے وو؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20039, 'Ezekiel 27:33', 'Ezekiel', 27, 33, '&nbsp;کله چې به ستا د تجارت مال په سمندر کښې نورو مُلکونو ته وړلے کېدو، تا ډېر مُلکونه ماړۀ کړل. ستا د ډېر مال دولت او مال سره تا د زمکې بادشاهان ماړۀ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20040, 'Ezekiel 27:34', 'Ezekiel', 27, 34, '&nbsp;اوس تۀ د سمندر په ژورو اوبو کښې مات او ډوب شوے يې، ستا سامانونه او ستا کارکوونکى ټول تا سره لاندې ډوب شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20041, 'Ezekiel 27:35', 'Ezekiel', 27, 35, '&nbsp;هر هغه څوک چې د سمندر په غاړه اوسيږى، هغوئ تا ته حېران دى، د هغوئ بادشاهان يرې اخستى دى او پرېشانه شوى دى او شکلونه يې د يرې نه په بله اوړېدلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20042, 'Ezekiel 27:36', 'Ezekiel', 27, 36, '&nbsp;د قومونو سوداګرو ستا په حقله په خپلو کښې وائى چې توبه توبه، کله چې هغوئ ستا خراب اَنجام وليدو او تۀ د تل دپاره نيست نابود شوې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20043, 'Ezekiel 28:1', 'Ezekiel', 28, 1, '&nbsp;د مالِک خُدائ کلام په ما نازل شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20044, 'Ezekiel 28:2', 'Ezekiel', 28, 2, '&nbsp;”اے بنى آدمه، د صور حکمران ته ووايه، مالِک قادر مطلق خُدائ داسې فرمائى چې تا د خپل زړۀ په مغرورتيا کښې وئيل چې، زۀ خُدائ يم او زۀ د خُدائ په تخت د سمندر په زړۀ کښې ناست يم. خو تۀ انسان يې او خُدائ پاک نۀ يې، اګر چې ستا دا خيال دے چې تۀ د خُدائ په شان هوښيار يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20045, 'Ezekiel 28:3', 'Ezekiel', 28, 3, '&nbsp;ولې تۀ دانيال نه ډېر هوښيار يې چې يو راز هم ستا نه پټ نۀ دے؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20046, 'Ezekiel 28:4', 'Ezekiel', 28, 4, '&nbsp;ستا په خپل عقل او پوهه تا د خپل ځان دپاره مال دولت راجمع کړو او په خپله خزانه کښې دې سرۀ او سپين زر راغونډ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20047, 'Ezekiel 28:5', 'Ezekiel', 28, 5, '&nbsp;په تجارت کښې د ډيرې پوهې په ذريعه تا خپل مال دولت زيات کړو، او د مال دولت په وجه ستا زړۀ ډېر مغروره شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20048, 'Ezekiel 28:6', 'Ezekiel', 28, 6, '&nbsp;نو په دې وجه مالِک قادر مطلق خُدائ داسې فرمائى چې، ځکه چې ستا خيال دا دے چې تۀ هوښيار يې، لکه د خُدائ په شان هوښيار يې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20049, 'Ezekiel 28:7', 'Ezekiel', 28, 7, '&nbsp;زۀ به ستا خلاف د غېرو قومونو نه د ټولو نه زيات بې‌رحمه خلق راولم، هغوئ به ستا د حُسن او عقل خلاف خپلې تُورې راوکاږى او ستا ځلېدونکے شان او شوکت به پليت کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20050, 'Ezekiel 28:8', 'Ezekiel', 28, 8, '&nbsp;هغوئ به تا کندې ته ښکته کړى او تۀ به د سمندر په زړۀ کښې په بې‌دردۍ سره مړ شې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20051, 'Ezekiel 28:9', 'Ezekiel', 28, 9, '&nbsp;ولې تۀ به بيا د قاتلانو په مخکښې ووائې چې زۀ خُدائ يم؟ هيڅکله نه. تۀ به صرف انسان يې، خُدائ نه، د هغوئ په لاسونو کښې څوک چې تا حلالوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20052, 'Ezekiel 28:10', 'Ezekiel', 28, 10, '&nbsp;تۀ به د غېرو قومونو په لاسونو لکه د ناسنتو په شان مړ شې. ما مالِک قادر مطلق خُدائ دا فرمائيلى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20053, 'Ezekiel 28:11', 'Ezekiel', 28, 11, '&nbsp;د مالِک خُدائ کلام په ما نازل شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20054, 'Ezekiel 28:12', 'Ezekiel', 28, 12, '&nbsp;”اے بنى آدمه، د صور د بادشاه په حقله د غم مرثيه ووايه او هغۀ ته ووايه چې، مالِک قادر مطلق خُدائ داسې فرمائى چې، تۀ د کامليت نمونه وې، د عقل نه ډک وې او ستا حُسن د کمال وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20055, 'Ezekiel 28:13', 'Ezekiel', 28, 13, '&nbsp;تۀ په باغِ عدن کښې، د مالِک خُدائ په باغ کښې وې، هر قسم قيمتى کاڼو لکه ياقوت، طوپاز، هيره، ايکوامرين، اونيکس کاڼى، جاسپر، نيلم، زمرد او لعلونو تۀ ښائسته کړے وې. تۀ د سرو زرو کار ښکلے کړے وې. په کومه ورځ چې ستا تخليق وشو دا ستا دپاره تيار کړے شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20056, 'Ezekiel 28:14', 'Ezekiel', 28, 14, '&nbsp;ما تۀ د وزرو والا مخلوق په شان مسح شوے او ساتونکے مقرر کړې او تۀ د خُدائ پاک په مقدس غر وې، او تۀ د بلېدونکو کاڼو په مينځ کښې ګرځېدلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20057, 'Ezekiel 28:15', 'Ezekiel', 28, 15, '&nbsp;ستا د پېدايښت د ورځې نه ستا چال چلن بې‌داغه وو تر دې چې په تا کښې بدکارى پېدا شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20058, 'Ezekiel 28:16', 'Ezekiel', 28, 16, '&nbsp;تۀ د خپل ډېر زيات تجارت په وجه د ظلم زياتې نه ډک شوې او ګناه دې وکړه. نو ما بيا تۀ په بې‌عزتۍ سره د خُدائ پاک د غرۀ نه وشړلې، او ما تۀ اے حفاظت کوونکې فرښتې د هغه بلېدونکو کاڼو نه وشړلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20059, 'Ezekiel 28:17', 'Ezekiel', 28, 17, '&nbsp;ستا زړۀ په خپل حُسن باندې مغروره شو، او تا خپل عقل د خپل شان او شوکت په وجه خراب کړو. نو ما تۀ زمکې ته راوغورزولې، او بادشاهانو ته مې تماشه جوړه کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20060, 'Ezekiel 28:18', 'Ezekiel', 28, 18, '&nbsp;تا په خپلو ډېرو ګناهونو او بې‌ايمانه تجارت خپل د عبادت ځايونه ګنده کړل. نو ما په تا اور ولګولو او هغۀ تۀ وسوزولې، او تۀ مې په زمکه د ټولو هغه کسانو په وړاندې په ايرو بدل کړې چې ستا تماشه يې کوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20061, 'Ezekiel 28:19', 'Ezekiel', 28, 19, '&nbsp;ټولو هغه مُلکونو چې تۀ يې پېژندلې تا ته حېران دى، ستا مرګ به ډېر خطرناک وى او تۀ به نور په دُنيا کښې پاتې نۀ شې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20062, 'Ezekiel 28:20', 'Ezekiel', 28, 20, '&nbsp;د مالِک خُدائ کلام په ما نازل شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20063, 'Ezekiel 28:21', 'Ezekiel', 28, 21, '&nbsp;”اے بنى آدمه، خپل مخ دې د صيدا خلاف کړه، د هغې خلاف پېشګوئې وکړه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20064, 'Ezekiel 28:22', 'Ezekiel', 28, 22, '&nbsp;او ووايه چې مالِک قادر مطلق خُدائ داسې فرمائى چې، زۀ ستا خلاف يم اے صيدا، او زۀ به په تا کښې جلال حاصل کړم. نو هغوئ به په دې پوهه شى چې زۀ مالِک خُدائ يم. کله چې زۀ په هغې د سزا فېصله وکړم او خپل ځان په هغې کښې مقدس ښکاره کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20065, 'Ezekiel 28:23', 'Ezekiel', 28, 23, '&nbsp;زۀ به په هغې وبا راولم او د هغې په کوڅو کښې به وينې روانې کړم. د هرې خوا نه به په تا حملې کيږى، ستا خلق به په کښې په تُوره مړۀ شى. نو بيا به هغوئ پوهه شى چې زۀ مالِک خُدائ يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20066, 'Ezekiel 28:24', 'Ezekiel', 28, 24, '&nbsp;”د بنى اِسرائيلو د خلقو به نور کينه لرونکى ګاونډيان نۀ وى کوم چې لکه د درد ورکونکى ازغو او تېرۀ غنو په شان وُو. نو بيا به هغوئ پوهه شى چې زۀ مالِک خُدائ يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20067, 'Ezekiel 28:25', 'Ezekiel', 28, 25, '&nbsp;مالِک قادر مطلق خُدائ داسې فرمائى چې، کله چې زۀ د بنى اِسرائيلو قوم د هغه مُلکونو نه راغونډ کړم کومو مُلکونو ته چې هغوئ خوارۀ وارۀ شوى وُو، زۀ به د هغوئ په مينځ کښې او د نورو قومونو په وړاندې خپل ځان مقدس وښايم. نو بيا به هغوئ په خپل مُلک کښې اوسيږى، کوم چې ما خپل خِدمتګار يعقوب له ورکړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20068, 'Ezekiel 28:26', 'Ezekiel', 28, 26, '&nbsp;هغوئ به هلته په امن سره ژوند تېروى او هغوئ به کورونه جوړ کړى او د انګورو بوټى به وکَرى. زۀ به د هغوئ هغه ټولو ګاونډيانو له سزا ورکړم چا چې ورپورې ټوقې کړې وې. نو بيا به هغوئ پوهه شى چې زۀ د هغوئ مالِک قادر مطلق خُدائ يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20069, 'Ezekiel 29:1', 'Ezekiel', 29, 1, '&nbsp;زمونږ د جلاوطنۍ د لسم کال د لسمې مياشتې په دولسمه ورځ د مالِک خُدائ کلام په ما نازل شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20070, 'Ezekiel 29:2', 'Ezekiel', 29, 2, '&nbsp;”اے بنى آدمه، د مِصر د بادشاه فِرعون په خلاف خپل مخ ورواړوه. د هغۀ او د ټول مِصر خلاف پېشګوئې وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20071, 'Ezekiel 29:3', 'Ezekiel', 29, 3, '&nbsp;هغۀ ته ووايه چې مالِک قادر مطلق خُدائ داسې فرمائى چې، اے د مِصر بادشاه فِرعونه، زۀ ستا خلاف يم، تۀ لکه د يو لوئ اژدها په شان په خپلو نِهرونو کښې غزېدلے يې او تۀ دا وائې چې دريائے نيل زما دے او دا ما د خپل ځان دپاره جوړ کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20072, 'Ezekiel 29:4', 'Ezekiel', 29, 4, '&nbsp;زۀ به ستا په خولۀ کښې کُنډه واچوم او د هغه نِهرونو ټول کبان به ستا څرمن پورې ونښلوم. او زۀ به تا سره د هغه ټولو کبانو د نِهرونو نه راوکاږم کوم چې ستا څرمن پورې انښتى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20073, 'Ezekiel 29:5', 'Ezekiel', 29, 5, '&nbsp;زۀ به تا او ستا د نِهرونو هغه ټول کبان په صحرا کښې پرېږدم. تۀ به په اوچه زمکه پروت يې او تۀ به نۀ راغونډ او نۀ اوچت کړے شې. زۀ به تا د زمکې د ځناورو او د هوا د مارغانو خوراک کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20074, 'Ezekiel 29:6', 'Ezekiel', 29, 6, '&nbsp;نو بيا به هغوئ ټول په دې پوهه شى څوک چې په مِصر کښې اوسيږى چې زۀ مالِک خُدائ يم. تۀ د بنى اِسرائيلو د قوم دپاره صرف د لوخې امسا په شان وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20075, 'Ezekiel 29:7', 'Ezekiel', 29, 7, '&nbsp;کله چې تۀ هغوئ په خپل لاس کښې ونيولې نو تا دړه وکړه او د هغوئ اوږه دې سورۍ کړه، او کله چې هغوئ په تا تکيه وکړه، نو ستا ملا ماته شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20076, 'Ezekiel 29:8', 'Ezekiel', 29, 8, '&nbsp;نو په دې وجه مالِک قادر مطلق خُدائ داسې فرمائى چې، زۀ به ستاسو خلاف تُوره راواخلم او ستاسو سړى او د هغوئ ځناور به قتل کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20077, 'Ezekiel 29:9', 'Ezekiel', 29, 9, '&nbsp;نو مِصر به په صحرا او شاړه زمکه بدل شى. نو بيا به هغوئ په دې پوهه شى چې زۀ مالِک خُدائ يم. ځکه چې تا وئيل چې، دريائے نيل زما دے، هغه ما جوړ کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20078, 'Ezekiel 29:10', 'Ezekiel', 29, 10, '&nbsp;نو په دې وجه زۀ ستا او ستا د نِهرونو خلاف يم، او زۀ به د مِصر مُلک تباه او وران ويجاړ کړم د مجدال نه تر اسوان پورې، او د ايتهوپيا د سرحدونو پورې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20079, 'Ezekiel 29:11', 'Ezekiel', 29, 11, '&nbsp;نۀ به د انسان او نۀ به د ځناورو قدم په تا تېر شى، او د څلوېښتو کالو پورې به په کښې هيڅ څوک هم نۀ اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20080, 'Ezekiel 29:12', 'Ezekiel', 29, 12, '&nbsp;زۀ به د مِصر حال د خوا او شا ورانو مُلکونو نه بدتر کړم. او د هغۀ ښارونه به د تباه شوو ښارونو په مينځ کښې د څلوېښتو کالو پورې تباه پراتۀ وى. او زۀ به مِصريان په نورو قومونو او مُلکونو کښې خوارۀ وارۀ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20081, 'Ezekiel 29:13', 'Ezekiel', 29, 13, '&nbsp;نو مالِک قادر مطلق خُدائ داسې فرمائى چې، زۀ به مِصريان د څلوېښتم کال په آخر کښې د هغه مُلکونو نه رايوځائ کړم کوم ته چې هغوئ خوارۀ شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20082, 'Ezekiel 29:14', 'Ezekiel', 29, 14, '&nbsp;زۀ به هغوئ بيا بحال کړم او خپل اصلى او د پلار نيکۀ مُلک جنوبى مِصر ته راولم. او هلته به د هغوئ يو کمزورے بادشاهت وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20083, 'Ezekiel 29:15', 'Ezekiel', 29, 15, '&nbsp;دا به د نورو بادشاهتونو په مينځ کښې د ټولو نه کمزورے بادشاهت وى او کله به هم په نورو بادشاهتونو خپل ځان اوچت نۀ کړى. زۀ به دا دومره کمزورے کړم چې دا به هيڅکله هم په نورو قومونو حکومت ونۀ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20084, 'Ezekiel 29:16', 'Ezekiel', 29, 16, '&nbsp;بنى اِسرائيل به نور په مِصر تکيه نۀ کوى خو دا به هغوئ ته د خپلې هغه ګناه کولو يو يادګار وى چې کله به دوئ د هغوئ نه مدد غوښتلو. نو بيا به هغوئ په دې پوهه شى چې زۀ مالِک خُدائ يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20085, 'Ezekiel 29:17', 'Ezekiel', 29, 17, '&nbsp;په اوويشتم کال، د وړومبۍ مياشتې په وړومبۍ ورځ، د مالِک خُدائ کلام په ما نازل شو چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20086, 'Ezekiel 29:18', 'Ezekiel', 29, 18, '&nbsp;”اے بنى آدمه، د بابل بادشاه خپل فوجيان د صور خلاف د حملې دپاره ورولېږل، تر دې چې د سخت جنګ په وجه ګنجيان شول او د هغوئ اوږې پولۍ شوې، خو د دې ټول تکليف باوجود بادشاه او هغوئ تش لاس راغلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20087, 'Ezekiel 29:19', 'Ezekiel', 29, 19, '&nbsp;نو په دې وجه مالِک قادر مطلق خُدائ داسې فرمائى چې، زۀ د مِصر مُلک نبوکدنضر د بابل بادشاه له ورکوم، او هغه به د دې مال دولت ځان سره يوسى. هغه به دا لوټ کړى، خپلو فوجيانو ته به يې په تنخواه کښې حساب کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20088, 'Ezekiel 29:20', 'Ezekiel', 29, 20, '&nbsp;ما هغۀ ته په انعام کښې مِصر ورکړو د هغه کار په بدل کښې کوم چې هغۀ او د هغۀ فوجيانو زما دپاره کړے دے. مالِک خُدائ داسې فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20089, 'Ezekiel 29:21', 'Ezekiel', 29, 21, '&nbsp;چې کله دا هر څۀ وشى نو زۀ به بنى اِسرائيلو له نوے طاقت ورکړم. اے حزقى‌ايله، په هغه وخت به زۀ ستا خولۀ کولاو کړم او تۀ به دوباره د هغوئ په مينځ کښې خبرې شروع کړې. نو بيا به هغوئ پوهه شى چې زۀ مالِک قادر مطلق خُدائ يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20090, 'Ezekiel 30:1', 'Ezekiel', 30, 1, '&nbsp;د مالِک خُدائ کلام په ما نازل شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20091, 'Ezekiel 30:2', 'Ezekiel', 30, 2, '&nbsp;”اے بنى آدمه پېشګوئې وکړه او ووايه، مالِک قادر مطلق خُدائ داسې فرمائى چې، وير وکړئ او ووايئ، افسوس دې وى په هغه ورځ', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20092, 'Ezekiel 30:3', 'Ezekiel', 30, 3, '&nbsp;ځکه هغه ورځ رانزدې ده، د مالِک خُدائ ورځ رانزدې ده، د تورو تيارو ورځ، دا به د قومونو دپاره د قيامت ورځ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20093, 'Ezekiel 30:4', 'Ezekiel', 30, 4, '&nbsp;د مِصر خلاف به تُوره رانازله شى، او په ايتهوپيا باندې به غم نازل شى. کله چې مِصر کښې مړى وشى، د هغۀ مال دولت به لوټ شى او د هغۀ بنيادونه به د بېخه وران شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20094, 'Ezekiel 30:5', 'Ezekiel', 30, 5, '&nbsp;د ايتهوپيا، ليبيا، د لِديه، عربو، او د کوب زما د غوره شوى مُلک خلق به د مِصر سره په تُوره قتل کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20095, 'Ezekiel 30:6', 'Ezekiel', 30, 6, '&nbsp;مالِک قادر مطلق خُدائ داسې فرمائى چې، مِصر او د هغۀ اِتحاديان به ووژلے شى او د هغۀ د کبر کاسه به نسکوره شى. د مجدال نه تر اسوان پورې به هغوئ د هغۀ سره په تُوره قتل کړے شى، مالِک قادر مطلق خُدائ داسې فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20096, 'Ezekiel 30:7', 'Ezekiel', 30, 7, '&nbsp;هغوئ به د نورو ورانو مُلکونو په مينځ کښې برباد وى، او د هغوئ ښارونه به د تباه شوو ښارونو په مينځ کښې پراتۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20097, 'Ezekiel 30:8', 'Ezekiel', 30, 8, '&nbsp;نو بيا به هغوئ په دې پوهه شى چې زۀ مالِک خُدائ يم، کله چې زۀ په مِصر اور ولګوم او د هغۀ ټول مددګاران قتل شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20098, 'Ezekiel 30:9', 'Ezekiel', 30, 9, '&nbsp;په هغه ورځ به پېغام رسوونکى زما نه په کشتۍ کښې روان شى چې د ايتهوپيا مغروره خلق ويروى. د مِصر د تباهۍ په ورځ به هغوئ ډېر پرېشانه شى، په يقين سره هغه ورځ راروانه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20099, 'Ezekiel 30:10', 'Ezekiel', 30, 10, '&nbsp;مالِک قادر مطلق خُدائ داسې فرمائى چې، زۀ به د بابل بادشاه نبوکدنضر په وسيله ګڼ مِصريان ختم کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20100, 'Ezekiel 30:11', 'Ezekiel', 30, 11, '&nbsp;هغه او د هغۀ فوجيان چې په ټولو قومونو کښې ظالمان دى د دې مُلک د تباهۍ دپاره به راوستے شى. هغوئ به خپلې تُورې د مِصر خلاف راوباسى او هغه به د مړو نه ډک کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');